async function main() {
  console.log('Importing full OUI spinout portfolio (238 companies)...\n')

  const oxford = await prisma.university.upsert({
    where: { slug: 'oxford' },
    update: {},
    create: { slug: 'oxford', name: 'University of Oxford' },
  })

  let count = 0
  let skipped = 0
  for (const co of OUI_FULL_PORTFOLIO) {
    const slug = slugify(co.name)
    if (!slug) { skipped++; continue }
    await prisma.company.upsert({
      where: { universityId_slug: { universityId: oxford.id, slug } },
      update: {
        description: co.description,
        tags: co.tags,
        sector: co.sector,
        segment: co.sector,
        fundingStage: co.fundingStage,
        website: co.website ?? null,
        isEcosystemOrg: false,
      },
      create: {
        universityId: oxford.id,
        slug,
        name: co.name,
        description: co.description,
        website: co.website ?? null,
        tags: co.tags,
        sector: co.sector,
        segment: co.sector,
        fundingStage: co.fundingStage,
        isEcosystemOrg: false,
        newThisWeek: false,
      },
    })
    count++
  }
  console.log(`  ✓ ${count} OUI spinout companies imported (${skipped} skipped)`)
}

main()
  .catch((e) => {
    console.error(e)
    process.exit(1)
  })
  .finally(() => prisma.$disconnect())
